  1→/**
  2→ * Standalone WebSocket relay server for the thos dashboard.
  3→ *
  4→ * Runs on port 9900 alongside Next.js (started via `concurrently` in the
  5→ * `dev` script). It cannot be a Next.js API route because API routes don't
  6→ * support persistent WebSocket connections.
  7→ *
  8→ * ## Architecture
  9→ *
 10→ * Two WebSocket path families:
 11→ * - `/browser`          — the React dashboard connects here (supports multiple tabs).
 12→ * - `/claude/:agentId`  — each Claude CLI connects here (passed as `--sdk-url`).
 13→ *
 14→ * The server supports multiple concurrent agents, each tracked in the
 15→ * `agents` Map keyed by a short random ID.
 16→ *
 17→ * ## Connection flow (browser)
 18→ *
 19→ * On browser connect, the server sends two small messages:
 20→ * 1. `agent_list`  — metadata for all agents (sidebar).
 21→ * 2. `task_list`   — all tasks.
 22→ *
 23→ * Message histories are NOT sent eagerly. They are loaded lazily: the
 24→ * browser sends `{ type: "request_history", agentId }` when the user
 25→ * selects an agent, and the server responds with `message_history` for
 26→ * that single agent. This avoids sending megabytes of JSON on connect,
 27→ * which caused multi-minute loading times on mobile networks.
 28→ *
 29→ * Live messages for active agents are still broadcast to all browsers
 30→ * via `relay` messages in real time.
 31→ *
 32→ * ## Message flow (spawning)
 33→ *
 34→ * 1. Browser sends `{ type: "spawn", prompt }`.
 35→ * 2. Server creates agent entry, spawns `claude --sdk-url ws://localhost:9900/claude/<agentId>`.
 36→ * 3. CLI connects on `/claude/<agentId>`, sends `system/hook_started` then `system/hook_response`.
 37→ * 4. On `hook_response`, server forwards the pending prompt to the CLI.
 38→ * 5. CLI sends `system/init`, then `assistant` messages, then `result`.
 39→ * 6. All CLI messages are relayed to the browser as `{ type: "relay", agentId, message }`.
 40→ * 7. `control_request` messages (tool approval) are relayed to the browser;
 41→ *    the browser's `control_response` (with `agentId`) is forwarded back to the right CLI.
 42→ *
 43→ * ## Resilience features
 44→ *
 45→ * - **Server-side message history** — every relay message is stored per-agent.
 46→ * - **File persistence** — agent state + history persisted to disk, survives restarts.
 47→ * - **Multi-browser** — multiple tabs can connect simultaneously.
 48→ * - **tmux survival** — tmux sessions are NOT killed on server restart; CLI processes
 49→ *   can reconnect to the new server if they retry their WebSocket connection.
 50→ * - **Message queuing** — messages sent while CLI is disconnected are queued and flushed on reconnect.
 51→ * - **Disconnect notifications** — browser is notified of CLI disconnect/reconnect.
 52→ * - **Lazy history** — message histories loaded on demand per agent, not on connect.
 53→ */
 54→import { WebSocketServer, WebSocket } from "ws";
 55→import { execSync, spawn } from "child_process";
 56→import { randomBytes } from "crypto";
 57→import type { IncomingMessage } from "http";
 58→import type {
 59→  BrowserMessage,
 60→  ClaudeMessage,
 61→  ServerMessage,
 62→  AgentStatus,
 63→  AgentInfo,
 64→  Task,
 65→} from "../lib/types";
 66→import { SessionStore, type PersistedAgent } from "./session-store";
 67→import { TaskStore } from "./task-store";
 68→
 69→const PORT = 9900;
 70→const TMUX_SESSION_PREFIX = "thos-agent";
 71→
 72→/** Check if an IP is localhost or in the Tailscale CGNAT range (100.64.0.0/10). */
 73→function isAllowedIP(ip: string | undefined): boolean {
 74→  if (!ip) return false;
 75→  // Strip IPv6-mapped IPv4 prefix
 76→  const addr = ip.startsWith("::ffff:") ? ip.slice(7) : ip;
 77→  if (addr === "127.0.0.1" || addr === "::1" || addr === "localhost") return true;
 78→  // Tailscale CGNAT: 100.64.0.0/10 → 100.64.0.0 – 100.127.255.255
 79→  const parts = addr.split(".");
 80→  if (parts.length !== 4) return false;
 81→  const first = parseInt(parts[0], 10);
 82→  const second = parseInt(parts[1], 10);
 83→  return first === 100 && second >= 64 && second <= 127;
 84→}
 85→
 86→const wss = new WebSocketServer({
 87→  port: PORT,
 88→  verifyClient: (info) => {
 89→    const ip = info.req.socket.remoteAddress;
 90→    const allowed = isAllowedIP(ip);
 91→    if (!allowed) console.log(`[ws] rejected connection from ${ip}`);
 92→    return allowed;
 93→  },
 94→});
 95→const store = new SessionStore();
 96→
 97→// ── Multi-agent state ──────────────────────────────────────────────────────
 98→
 99→interface AgentState {
100→  agentId: string;
101→  claudeSocket: WebSocket | null;
102→  tmuxSession: string | null;
103→  pendingPrompt: string | null;
104→  status: AgentStatus;
105→  label: string;
106→  createdAt: number;
107→  /** Captured from system/init, used in subsequent user messages. */
108→  sessionId: string | null;
109→  /** Stores control_request inputs keyed by request_id, for building control_responses. */
110→  pendingControlRequests: Map<string, Record<string, unknown>>;
111→  /** All messages sent to the browser for this agent (source of truth). */
112→  messageHistory: ServerMessage[];
113→  /** Messages queued while CLI is disconnected, flushed on reconnect. */
114→  pendingMessages: string[];
115→}
116→
117→const agents = new Map<string, AgentState>();
118→const taskStore = new TaskStore();
119→const tasks = new Map<string, Task>();
120→
121→/** All active browser connections (supports multiple tabs). */
122→const browserSockets = new Set<WebSocket>();
123→
124→/** Generate a short random agent ID. */
125→function newAgentId(): string {
126→  return randomBytes(4).toString("hex");
127→}
128→
129→// ── tmux helpers ───────────────────────────────────────────────────────────
130→
131→/** Return the set of currently alive tmux session names matching the thos prefix. */
132→function listAliveTmuxSessions(): Set<string> {
133→  try {
134→    const output = execSync("tmux list-sessions -F '#{session_name}'", {
135→      encoding: "utf-8",
136→    }).trim();
137→    if (!output) return new Set();
138→    return new Set(output.split("\n").filter((s) => s.startsWith(TMUX_SESSION_PREFIX)));
139→  } catch {
140→    return new Set();
141→  }
142→}
143→
144→// ── Persistence helpers ────────────────────────────────────────────────────
145→
146→/** Build a PersistedAgent snapshot from live state. */
147→function toPersistedAgent(agent: AgentState): PersistedAgent {
148→  return {
149→    id: agent.agentId,
150→    state: {
151→      agentId: agent.agentId,
152→      status: agent.status,
153→      tmuxSession: agent.tmuxSession,
154→      label: agent.label,
155→      createdAt: agent.createdAt,
156→      sessionId: agent.sessionId,
157→    },
158→    messageHistory: agent.messageHistory,
159→  };
160→}
161→
162→/**
163→ * Compact a message history by deduplicating cumulative snapshots.
164→ * Keeps only the last version of each assistant/user message ID.
165→ * Called on restore to shrink legacy bloated histories.
166→ */
167→function compactHistory(history: ServerMessage[]): ServerMessage[] {
168→  // Build a map of msgId → last index
169→  const lastIndex = new Map<string, number>();
170→  for (let i = 0; i < history.length; i++) {
171→    const id = getRelayMessageId(history[i]);
172→    if (id) lastIndex.set(id, i);
173→  }
174→  // Keep only messages that are either non-deduplicable or the last occurrence
175→  return history.filter((msg, i) => {
176→    const id = getRelayMessageId(msg);
177→    if (!id) return true; // non-relay or no message ID — always keep
178→    return lastIndex.get(id) === i;
179→  });
180→}
181→
182→/** Persist agent state (debounced — use for streaming events). */
183→function persistAgent(agent: AgentState) {
184→  store.save(toPersistedAgent(agent));
185→}
186→
187→/** Persist agent state immediately (use for critical state changes). */
188→function persistAgentSync(agent: AgentState) {
189→  store.saveSync(toPersistedAgent(agent));
190→}
191→
192→// ── Restore from disk on startup ───────────────────────────────────────────
193→
194→function restoreAgents() {
195→  const persisted = store.loadAll();
196→  const aliveSessions = listAliveTmuxSessions();
197→
198→  for (const p of persisted) {
199→    const agent: AgentState = {
200→      agentId: p.state.agentId,
201→      claudeSocket: null,
202→      tmuxSession: p.state.tmuxSession,
203→      pendingPrompt: null,
204→      status: p.state.status,
205→      label: p.state.label,
206→      createdAt: p.state.createdAt,
207→      sessionId: p.state.sessionId,
208→      pendingControlRequests: new Map(),
209→      messageHistory: compactHistory(p.messageHistory),
210→      pendingMessages: [],
211→    };
212→
213→    // Determine status for agents that were active when the server last ran
214→    if (agent.status !== "done" && agent.status !== "error") {
215→      const tmuxAlive = agent.tmuxSession ? aliveSessions.has(agent.tmuxSession) : false;
216→      if (tmuxAlive) {
217→        // tmux session still alive — CLI may reconnect to this server
218→        agent.status = "disconnected";
219→        console.log(`[restore] agent ${agent.agentId} — tmux alive, waiting for CLI reconnect`);
220→      } else {
221→        // tmux session gone — agent is archived
222→        agent.status = "done";
223→        console.log(`[restore] agent ${agent.agentId} — tmux dead, archived`);
224→      }
225→    }
226→
227→    agents.set(agent.agentId, agent);
228→    const originalCount = p.messageHistory.length;
229→    const compactedCount = agent.messageHistory.length;
230→    const saved = originalCount - compactedCount;
231→    console.log(`[restore] agent ${agent.agentId} (status=${agent.status}, ${compactedCount} messages${saved > 0 ? `, compacted from ${originalCount} (−${saved})` : ""})`);
232→
233→    // Persist compacted history back to disk
234→    if (saved > 0) {
235→      persistAgentSync(agent);
236→    }
237→  }
238→  console.log(`[restore] loaded ${persisted.length} agents from disk`);
239→}
