368→// ── Agent lifecycle ────────────────────────────────────────────────────────
369→
370→/**
371→ * Stop a running agent by killing its tmux session and closing the CLI socket.
372→ * The agent remains in the Map (status set to "done") so it can be viewed/deleted later.
373→ */
374→function stopAgent(agentId: string) {
375→  const agent = agents.get(agentId);
376→  if (!agent) return;
377→
378→  if (agent.tmuxSession) {
379→    try {
380→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
381→      console.log(`[tmux] killed session ${agent.tmuxSession}`);
382→    } catch {
383→      // Session may already be dead
384→    }
385→  }
386→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
387→    agent.claudeSocket.close();
388→  }
389→  agent.claudeSocket = null;
390→  setAgentStatus(agentId, "done");
391→}
392→
393→/**
394→ * Permanently delete an agent: stop it, remove from Map, remove from disk.
395→ */
396→function deleteAgent(agentId: string) {
397→  const agent = agents.get(agentId);
398→  if (!agent) return;
399→
400→  if (agent.tmuxSession) {
401→    try {
402→      execSync(`tmux kill-session -t ${agent.tmuxSession}`, { stdio: "ignore" });
403→    } catch {}
404→  }
405→  if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
406→    agent.claudeSocket.close();
407→  }
408→  agents.delete(agentId);
409→  store.remove(agentId);
410→  broadcastAgentList();
411→}
412→
413→/**
414→ * Spawn a new Claude CLI process inside a tmux session.
415→ *
416→ * Creates a new agent entry, spawns the CLI with `--sdk-url` pointing to
417→ * `/claude/<agentId>`, and sends a `spawned` message to the browser.
418→ */
419→function spawnClaude(prompt: string): string {
420→  const agentId = newAgentId();
421→  const sessionName = `${TMUX_SESSION_PREFIX}-${agentId}`;
422→  const label = prompt.length > 60 ? prompt.slice(0, 57) + "..." : prompt;
423→
424→  const agent: AgentState = {
425→    agentId,
426→    claudeSocket: null,
427→    tmuxSession: null,
428→    pendingPrompt: prompt,
429→    status: "spawning",
430→    label,
431→    createdAt: Date.now(),
432→    sessionId: null,
433→    pendingControlRequests: new Map(),
434→    messageHistory: [],
435→    pendingMessages: [],
436→  };
437→  agents.set(agentId, agent);
438→
439→  // Notify browsers
440→  sendToBrowser({ type: "spawned", agentId });
441→  broadcastAgentList();
442→  persistAgentSync(agent);
443→
444→  // Build the claude command with CLAUDECODE unset to bypass nesting protection.
445→  // tmux new-session runs detached (-d) so spawn() returns immediately.
446→  const claudeCmd = `unset CLAUDECODE; exec claude --dangerously-skip-permissions --sdk-url ws://localhost:${PORT}/claude/${agentId}`;
447→
448→  const tmux = spawn("tmux", ["new-session", "-d", "-s", sessionName, "bash", "-c", claudeCmd], {
449→    stdio: "ignore",
450→  });
451→
452→  tmux.on("error", (err) => {
453→    console.error("[tmux spawn error]", err);
454→    setAgentStatus(agentId, "error");
455→    recordAndSend(agentId, { type: "error", agentId, error: `tmux error: ${err.message}` });
456→  });
457→
458→  tmux.on("exit", (code) => {
459→    if (code !== 0) {
460→      console.error(`[tmux] new-session exited with code ${code}`);
461→      setAgentStatus(agentId, "error");
462→      recordAndSend(agentId, { type: "error", agentId, error: `tmux exited with code ${code}` });
463→      return;
464→    }
465→    console.log(`[tmux] session ${sessionName} created — attach with: tmux attach -t ${sessionName}`);
466→    agent.tmuxSession = sessionName;
467→    broadcastAgentList();
468→    persistAgentSync(agent);
469→  });
470→
471→  return agentId;
472→}
473→
474→// ── Message handlers ───────────────────────────────────────────────────────
475→
476→/**
477→ * Process an incoming NDJSON message from a specific Claude CLI.
478→ *
479→ * Status flow matches the Companion protocol:
480→ * - hook_response → send pending prompt → "thinking"
481→ * - system/init   → "connected" + capture session_id
482→ * - assistant      → "thinking"
483→ * - result         → "connected" (CLI stays alive for multi-turn)
484→ * - CLI disconnect → "done" (handled in connection close handler)
485→ */
486→function handleClaudeMessage(agentId: string, raw: string) {
487→  const agent = agents.get(agentId);
488→  if (!agent) return;
489→
490→  let msg: ClaudeMessage;
491→  try {
492→    msg = JSON.parse(raw);
493→  } catch {
494→    console.error(`[claude:${agentId}] invalid JSON:`, raw);
495→    return;
496→  }
497→
498→  // Silently ignore keep_alive messages
499→  if (msg.type === "keep_alive") return;
500→
501→  console.log(`[claude:${agentId} →]`, msg.type, (msg as { subtype?: string }).subtype ?? "");
502→
503→  // After hook_response, send the pending prompt
504→  if (
505→    msg.type === "system" &&
506→    (msg as { subtype?: string }).subtype === "hook_response" &&
507→    agent.pendingPrompt &&
508→    agent.claudeSocket?.readyState === WebSocket.OPEN
509→  ) {
510→    const userMsg = JSON.stringify({
511→      type: "user",
512→      message: { role: "user", content: agent.pendingPrompt },
513→      parent_tool_use_id: null,
514→      session_id: agent.sessionId ?? "",
515→    });
516→    console.log(`[server → claude:${agentId}]`, userMsg);
517→    agent.claudeSocket.send(userMsg + "\n");
518→    agent.pendingPrompt = null;
519→    setAgentStatus(agentId, "thinking");
520→  }
521→
522→  // Track status based on message type
523→  if (msg.type === "system" && (msg as { subtype?: string }).subtype === "init") {
524→    // Capture session_id for subsequent user messages
525→    agent.sessionId = (msg as { session_id?: string }).session_id ?? null;
526→    setAgentStatus(agentId, "connected");
527→  } else if (msg.type === "assistant") {
528→    setAgentStatus(agentId, "thinking");
529→  } else if (msg.type === "result") {
530→    // CLI stays alive after result — ready for the next turn.
531→    // Status only goes to "done" when the CLI WebSocket actually closes.
532→    setAgentStatus(agentId, "connected");
533→  }
534→
535→  // Store control_request inputs for building proper responses later
536→  if (msg.type === "control_request") {
537→    const cr = msg as { request_id?: string; request?: { input?: Record<string, unknown> } };
538→    if (cr.request_id && cr.request?.input) {
539→      agent.pendingControlRequests.set(cr.request_id, cr.request.input);
540→    }
541→  }
542→
543→  // Record in history and relay to browsers
544→  recordAndSend(agentId, { type: "relay", agentId, message: msg });
545→}
546→
547→/**
548→ * Process an incoming JSON message from the browser.
549→ * - `spawn`: create a new agent (does NOT kill others).
550→ * - `send_message`: forward a follow-up user message to the specified agent.
551→ * - `control_response`: forward a tool allow/deny decision to the specified agent.
552→ * - `kill_agent`: stop the CLI and tmux session.
553→ * - `delete_agent`: permanently remove an agent.
554→ * - `rename_agent`: update an agent's label.
555→ * - `clear_history`: wipe an agent's message history.
556→ * - `request_history`: send message history for a single agent (lazy loading).
557→ * - `create_task` / `update_task` / `delete_task` / `delegate_task`: task CRUD.
558→ */
559→function handleBrowserMessage(raw: string, senderWs: WebSocket) {
560→  let msg: BrowserMessage;
561→  try {
562→    msg = JSON.parse(raw);
563→  } catch {
564→    console.error("[browser] invalid JSON:", raw);
565→    return;
566→  }
567→
568→  console.log("[browser →]", msg.type);
569→
570→  switch (msg.type) {
571→    case "spawn":
572→      spawnClaude(msg.prompt);
573→      break;
574→
575→    case "send_message": {
576→      const agent = agents.get(msg.agentId);
577→      if (!agent) {
578→        sendToBrowser({ type: "error", agentId: msg.agentId, error: "Unknown agent" });
579→        break;
580→      }
581→
582→      // Record the user message in history so it persists across reloads.
583→      // Do NOT broadcast — the sending browser already has it optimistically,
584→      // and other browsers will get it when they request_history.
585→      agent.messageHistory.push({
586→        type: "relay",
587→        agentId: msg.agentId,
588→        message: { type: "user", message: { role: "user", content: msg.content } },
589→      } as ServerMessage);
590→      persistAgent(agent);
591→
592→      if (agent.claudeSocket?.readyState === WebSocket.OPEN) {
593→        const userMsg = JSON.stringify({
594→          type: "user",
595→          message: { role: "user", content: msg.content },
596→          parent_tool_use_id: null,
597→          session_id: agent.sessionId ?? "",
598→        });
599→        agent.claudeSocket.send(userMsg + "\n");
600→        setAgentStatus(msg.agentId, "thinking");
601→      } else {
602→        // Queue message for delivery when CLI reconnects
603→        const userMsg = JSON.stringify({
604→          type: "user",
605→          message: { role: "user", content: msg.content },
606→          parent_tool_use_id: null,
607→          session_id: agent.sessionId ?? "",
608→        });
609→        agent.pendingMessages.push(userMsg);
610→        console.log(`[queue] queued message for agent ${msg.agentId} (${agent.pendingMessages.length} pending)`);
611→        persistAgentSync(agent);
612→      }
613→      break;
614→    }
615→
616→    case "control_response": {
617→      const agent = agents.get(msg.agentId);
618→      if (agent?.claudeSocket?.readyState === WebSocket.OPEN) {
619→        // Retrieve the original tool input to include as updatedInput (required by protocol)
620→        const originalInput = agent.pendingControlRequests.get(msg.request_id) ?? {};
621→        agent.pendingControlRequests.delete(msg.request_id);
622→
623→        // If the browser sent answers (from AskUserQuestion), merge them into the input
624→        const answers = (msg as { answers?: Record<string, string> }).answers;
625→        const updatedInput = answers
626→          ? { ...originalInput, answers }
627→          : originalInput;
628→
629→        const response = JSON.stringify({
630→          type: "control_response",
631→          response: {
632→            subtype: "success",
633→            request_id: msg.request_id,
634→            response: msg.allow
635→              ? { behavior: "allow", updatedInput }
636→              : { behavior: "deny", message: "Denied by user" },
637→          },
638→        });
639→        agent.claudeSocket.send(response + "\n");
640→      }
641→      break;
642→    }
643→
644→    case "kill_agent":
645→      stopAgent(msg.agentId);
646→      break;
647→
648→    case "delete_agent":
649→      deleteAgent(msg.agentId);
650→      break;
651→
652→    case "rename_agent": {
653→      const agent = agents.get(msg.agentId);
654→      if (!agent) break;
655→      agent.label = msg.label;
656→      broadcastAgentList();
657→      persistAgentSync(agent);
658→      break;
659→    }
660→
661→    case "clear_history": {
662→      const agent = agents.get(msg.agentId);
663→      if (!agent) break;
664→      agent.messageHistory = [];
665→      persistAgentSync(agent);
666→      sendToBrowser({ type: "history_cleared", agentId: msg.agentId });
667→      break;
668→    }
669→
670→    case "request_history": {
671→      console.log(`[browser] request_history for ${msg.agentId}`);
672→      sendHistoryToSocket(senderWs, msg.agentId);
673→      break;
674→    }
675→
676→    case "create_task": {
677→      const taskId = randomBytes(4).toString("hex");
678→      const task: Task = {
679→        id: taskId,
680→        title: msg.title,
681→        description: msg.description,
682→        status: "todo",
683→        priority: msg.priority,
684→        agentId: null,
685→        createdAt: Date.now(),
686→        updatedAt: Date.now(),
687→      };
688→      tasks.set(taskId, task);
689→      persistTasks();
690→      broadcastTaskList();
691→      break;
692→    }
693→
694→    case "update_task": {
695→      const task = tasks.get(msg.taskId);
696→      if (!task) break;
697→      Object.assign(task, msg.updates, { updatedAt: Date.now() });
698→      persistTasks();
699→      broadcastTaskList();
700→      break;
701→    }
702→
703→    case "delete_task": {
704→      tasks.delete(msg.taskId);
705→      persistTasks();
706→      broadcastTaskList();
707→      break;
708→    }
709→
710→    case "delegate_task": {
711→      const task = tasks.get(msg.taskId);
712→      if (!task) break;
713→      const prompt = `Task: ${task.title}\n\n${task.description}`;
714→      const agentId = spawnClaude(prompt);
715→      task.agentId = agentId;
716→      task.status = "in-progress";
717→      task.updatedAt = Date.now();
718→      persistTasks();
719→      broadcastTaskList();
720→      break;
721→    }
722→  }
723→}
724→
725→// ── Send message history to a single browser socket ────────────────────────
726→
727→/** Send initial state (agent list + tasks) to a newly connected browser. */
728→function sendFullStateToSocket(ws: WebSocket) {
729→  if (ws.readyState !== WebSocket.OPEN) return;
730→
731→  // Agent list (sidebar metadata) — message histories are loaded lazily on demand
732→  ws.send(JSON.stringify({ type: "agent_list", agents: buildAgentList() }));
733→
734→  // Task list
735→  ws.send(JSON.stringify({ type: "task_list", tasks: buildTaskList() }));
736→}
737→
738→/** Send message history for a single agent to a specific browser socket. */
739→function sendHistoryToSocket(ws: WebSocket, agentId: string) {
740→  const agent = agents.get(agentId);
741→  if (!agent || ws.readyState !== WebSocket.OPEN) return;
742→  ws.send(
743→    JSON.stringify({
744→      type: "message_history",
745→      agentId: agent.agentId,
746→      messages: agent.messageHistory,
747→    })
748→  );
749→}
750→
751→// ── Connection handler — route by URL path ────────────────────────────────
752→wss.on("connection", (ws: WebSocket, req: IncomingMessage) => {
753→  const path = req.url ?? "/";
754→  console.log(`[ws connected] path=${path}`);
755→
756→  if (path === "/browser") {
757→    // Send full state BEFORE adding to browserSockets so that live
758→    // relay broadcasts don't interleave with the history replay.
759→    sendFullStateToSocket(ws);
760→    browserSockets.add(ws);
761→
762→    ws.on("message", (data) => {
763→      handleBrowserMessage(data.toString(), ws);
764→    });
765→
766→    ws.on("close", () => {
767→      console.log("[browser disconnected]");
768→      browserSockets.delete(ws);
769→      // Do NOT kill agents — keep them alive for reconnect
770→    });
771→  } else if (path.startsWith("/claude/")) {
772→    // Parse agentId from /claude/<agentId>
773→    const agentId = path.slice("/claude/".length);
774→    const agent = agents.get(agentId);
775→
776→    if (!agent) {
777→      console.log(`[ws] unknown agentId: ${agentId}, closing`);
778→      ws.close();
779→      return;
780→    }
781→
782→    agent.claudeSocket = ws;
783→    console.log(`[claude:${agentId} CLI connected via WebSocket]`);
784→
785→    // Notify browsers that CLI is connected
786→    sendToBrowser({ type: "cli_connected", agentId });
787→
788→    // Flush any pending messages queued while CLI was disconnected
789→    if (agent.pendingMessages.length > 0) {
790→      console.log(`[flush] sending ${agent.pendingMessages.length} queued messages to agent ${agentId}`);
791→      for (const queued of agent.pendingMessages) {
792→        ws.send(queued + "\n");
793→      }
794→      agent.pendingMessages = [];
795→      persistAgentSync(agent);
796→    }
797→
798→    ws.on("message", (data) => {
799→      handleClaudeMessage(agentId, data.toString());
800→    });
801→
802→    ws.on("close", () => {
803→      console.log(`[claude:${agentId} CLI disconnected]`);
804→      if (agent.claudeSocket === ws) {
805→        agent.claudeSocket = null;
806→        if (agent.status !== "error") {
807→          setAgentStatus(agentId, "done");
808→          sendToBrowser({ type: "cli_disconnected", agentId });
809→
810→          // Auto-complete any task linked to this agent
811→          for (const task of tasks.values()) {
812→            if (task.agentId === agentId && task.status !== "done") {
813→              task.status = "done";
814→              task.updatedAt = Date.now();
815→              persistTasks();
816→              broadcastTaskList();
817→              break;
818→            }
819→          }
820→        }
821→      }
822→    });
823→  } else {
824→    console.log(`[ws] unknown path: ${path}, closing`);
825→    ws.close();
826→  }
827→});
828→
829→// ── Graceful shutdown ─────────────────────────────────────────────────────
830→
831→function shutdown() {
832→  console.log("[ws server] shutting down...");
833→
834→  // Persist all agents synchronously before exit — do NOT kill tmux sessions
835→  // so CLI processes can reconnect if the server restarts.
836→  const allPersisted = Array.from(agents.values()).map(toPersistedAgent);
837→  store.flushAll(allPersisted);
838→  console.log(`[ws server] saved ${allPersisted.length} agents to disk (tmux sessions preserved)`);
839→
840→  taskStore.flush(Array.from(tasks.values()));
841→  console.log(`[ws server] saved ${tasks.size} tasks to disk`);
842→
843→  wss.close();
844→  process.exit(0);
845→}
846→
847→process.on("SIGTERM", shutdown);
848→process.on("SIGINT", shutdown);
849→
850→console.log(`[ws server] listening on port ${PORT}`);
