 1→/**
 2→ * File-based task persistence for the thos dashboard.
 3→ *
 4→ * Stores all tasks in a single JSON file at `$TMPDIR/thos-tasks/tasks.json`.
 5→ * Uses the same debounced/sync write pattern as SessionStore.
 6→ */
 7→
 8→import { mkdirSync, writeFileSync, readFileSync, existsSync } from "fs";
 9→import { join } from "path";
10→import { tmpdir } from "os";
11→import type { Task } from "../lib/types";
12→
13→const TASK_DIR = join(tmpdir(), "thos-tasks");
14→const TASK_FILE = join(TASK_DIR, "tasks.json");
15→
16→export class TaskStore {
17→  private debounceTimer: ReturnType<typeof setTimeout> | null = null;
18→
19→  constructor() {
20→    mkdirSync(TASK_DIR, { recursive: true });
21→  }
22→
23→  /** Load all tasks from disk. Returns empty array if file missing. */
24→  loadAll(): Task[] {
25→    if (!existsSync(TASK_FILE)) return [];
26→    try {
27→      const raw = readFileSync(TASK_FILE, "utf-8");
28→      return JSON.parse(raw) as Task[];
29→    } catch (err) {
30→      console.error("[task-store] failed to load:", err);
31→      return [];
32→    }
33→  }
34→
35→  /** Debounced write (150ms). */
36→  save(tasks: Task[]): void {
37→    if (this.debounceTimer) clearTimeout(this.debounceTimer);
38→    this.debounceTimer = setTimeout(() => {
39→      this.debounceTimer = null;
40→      this.writeFile(tasks);
41→    }, 150);
42→  }
43→
44→  /** Immediate write for critical changes. */
45→  saveSync(tasks: Task[]): void {
46→    if (this.debounceTimer) {
47→      clearTimeout(this.debounceTimer);
48→      this.debounceTimer = null;
49→    }
50→    this.writeFile(tasks);
51→  }
52→
53→  /** Flush pending writes (for graceful shutdown). */
54→  flush(tasks: Task[]): void {
55→    if (this.debounceTimer) {
56→      clearTimeout(this.debounceTimer);
57→      this.debounceTimer = null;
58→    }
59→    this.writeFile(tasks);
60→  }
61→
62→  private writeFile(tasks: Task[]): void {
63→    try {
64→      writeFileSync(TASK_FILE, JSON.stringify(tasks, null, 2));
65→    } catch (err) {
66→      console.error("[task-store] failed to write:", err);
67→    }
68→  }
69→}
